return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'lo_LA','project-id-version'=>'Events Manager','pot-creation-date'=>'2026-11-19T13:03:30+00:00','po-revision-date'=>'2026-11-15 04:52:35+0000','x-generator'=>'Pixelite GlotPress Sync','messages'=>[' Maximum size permitted by WordPress is %s.'=>' ຂະໜາດສູງສຸດທີ່ WordPress ອະນຸຍາດແມ່ນ %s.',' is required.'=>' ຈຳເປັນຕ້ອງມີ.','"%1$s" could not be created: %2$s'=>'ບໍ່ສາມາດສ້າງ "%1$s" ໄດ້: %2$s','"%1$s" is not a field. Fields: %2$s.'=>'"%1$s" ບໍ່ແມ່ນຊ່ອງຂໍ້ມູນ. ຊ່ອງຂໍ້ມູນ: %2$s.','"%s" is neither a media ID nor a web address that can be reached.'=>'"%s" ບໍ່ແມ່ນທັງ ID ສື່ ແລະ ທີ່ຢູ່ເວັບທີ່ເຂົ້າເຖິງໄດ້.','"All events" link text'=>'ຂໍ້ຄວາມລິ້ງ "ກິດຈະກຳທັງໝົດ"','#s will be replaced by the date format below'=>'#s ຈະຖືກແທນທີ່ດ້ວຍຮູບແບບວັນທີຂ້າງລຸ່ມ','%1$s could not be updated yet, and Events Manager will keep retrying in the background: %2$s'=>'ຍັງບໍ່ສາມາດອັບເດດ %1$s ໄດ້, ແລະ Events Manager ຈະພະຍາຍາມຕໍ່ໃນພື້ນຫຼັງ: %2$s','%1$s of %2$s'=>'%1$s / %2$s','%1$s recommends %2$s version %3$s or greater installed. Earlier versions may cause unexpected issues.'=>'%1$s ແນະນຳໃຫ້ຕິດຕັ້ງ %2$s ເວີຊັນ %3$s ຫຼືສູງກວ່າ. ເວີຊັນກ່ອນໜ້ານັ້ນອາດເຮັດໃຫ້ເກີດບັນຫາທີ່ບໍ່ຄາດຄິດ.','%1$s requires %2$s version %3$s or greater installed.'=>'%1$s ຕ້ອງການໃຫ້ຕິດຕັ້ງ %2$s ເວີຊັນ %3$s ຫຼືສູງກວ່າ.','%1$s was updated, but the result could not be stored: %2$s'=>'%1$s ຖືກອັບເດດແລ້ວ, ແຕ່ບໍ່ສາມາດບັນທຶກຜົນລັບໄດ້: %2$s','%1$s will be set up automatically on %2$s.'=>'%1$s ຈະຖືກຕັ້ງຄ່າໂດຍອັດຕະໂນມັດໃນ %2$s.','%1$s: %2$d rows imported, %3$d skipped.'=>'%1$s: ນຳເຂົ້າ %2$d ແຖວ, ຂ້າມ %3$d ແຖວ.','%d Attendees'=>'%d ຜູ້ເຂົ້າຮ່ວມ','%d Pattern'=>'%d ແພັດເທີນ','%d Spaces'=>'%d ບ່ອນນັ່ງ','%d Tickets'=>'%d ປີ້','%d date'=>'%d ວັນທີ','%d event got an attendee form with its Event Tickets attendee fields.'=>'%d ກິດຈະກຳໄດ້ຮັບແບບຟອມຜູ້ເຂົ້າຮ່ວມພ້ອມຊ່ອງຜູ້ເຂົ້າຮ່ວມຂອງ Event Tickets.','%d events have been %s as they no longer match the recurrence pattern.'=>'%d ກິດຈະກຳຖື